// ==================== АНТЕННА (Slave + MPU-6500 + QMC5883L) ====================
#include <Servo.h>
#include <SoftwareSerial.h>
#include <Wire.h>
#include <FastIMU.h>
#include <EEPROM.h>

// ---------- IMU: MPU-6500 + QMC5883L ----------
MPU6500_QMC5883L IMU;
calData calib = { 0 };
bool imuInitialized = false;

// ---------- Сервоприводы ----------
Servo servoH;
Servo servoV;
const int PIN_H = 9;
const int PIN_V = 5;

// ---------- RS485 (SoftwareSerial) ----------
SoftwareSerial rs485(10, 11);       // RX = D10, TX = D11
const int RS485_DE_RE = 2;

// ---------- Состояние ----------
int angleH = 90;
int angleV = 90;
int azimuth = 0;
int targetAzimuth = 0;
bool stabilizationMode = false;

// ---------- PID ----------
float Kp = 0.8, Ki = 0.05, Kd = 0.3;
float errPrev = 0, integral = 0;
unsigned long lastPid = 0;

// ---------- Калибровка ----------
bool calibrating = false;
unsigned long calibStart = 0;
const unsigned long CALIB_DURATION = 20000;
byte calibStep = 0;

// ---------- EEPROM ----------
const int EEPROM_CALIB_FLAG = 8;
const int EEPROM_CALIB_BASE = 10;
const int EEPROM_IMU_FLAG = 100;
const int EEPROM_IMU_BASE = 110;
const int EEPROM_CALIB_VALUE = 0xCD;

// ---------- Тайминги ----------
unsigned long lastAzSend = 0;
const int AZ_SEND_INTERVAL = 100;
unsigned long lastReadRS = 0;
const int RS_READ_INTERVAL = 20;
unsigned long lastServo = 0;
const int SERVO_INTERVAL = 40;

// ---------- Приём RS485 ----------
String rxBuffer = "";

void setup() {
    Serial.begin(9600);
    rs485.begin(9600);
    pinMode(RS485_DE_RE, OUTPUT);
    digitalWrite(RS485_DE_RE, LOW);

    servoH.attach(PIN_H);
    servoV.attach(PIN_V);
    servoH.write(angleH);
    servoV.write(angleV);

    Wire.begin();
    Wire.setClock(400000);

    Serial.println(F("=== ANTENNA v3.0 with MPU-6500 ==="));
    Serial.println(F("Initializing IMU..."));

    int err = IMU.init(calib, 0x68);
    if (err != 0) {
        Serial.print(F("IMU init failed: "));
        Serial.println(err);
        while (1) {
            digitalWrite(13, !digitalRead(13));
            delay(200);
        }
    }

    imuInitialized = true;
    Serial.println(F("IMU initialized successfully"));

    loadCalibration();
    lastPid = millis();
    Serial.println(F("=== ANTENNA READY ==="));
}

void loop() {
    unsigned long now = millis();

    if (now - lastReadRS >= RS_READ_INTERVAL) {
        lastReadRS = now;
        readRS485();
    }

    if (calibrating) {
        runCalibration();
        return;
    }

    if (imuInitialized) {
        IMU.update();

        MagData mag;
        AccelData accel;
        IMU.getMag(&mag);
        IMU.getAccel(&accel);

        float roll = atan2(accel.accelY, accel.accelZ);
        float pitch = atan2(-accel.accelX, sqrt(accel.accelY * accel.accelY + accel.accelZ * accel.accelZ));

        float magX_comp = mag.magX * cos(pitch) + mag.magY * sin(roll) * sin(pitch) + mag.magZ * cos(roll) * sin(pitch);
        float magY_comp = mag.magY * cos(roll) - mag.magZ * sin(roll);

        float heading = atan2(magY_comp, magX_comp) * 180.0 / PI;
        if (heading < 0) heading += 360;
        if (heading > 360) heading -= 360;

        azimuth = (int)heading;
    }

    if (now - lastServo >= SERVO_INTERVAL) {
        lastServo = now;

        if (stabilizationMode) {
            stabilizeWithPid(now);
        }

        servoH.write(angleH);
        servoV.write(angleV);
    }

    if (now - lastAzSend >= AZ_SEND_INTERVAL) {
        lastAzSend = now;
        String pkt = "A:";
        pkt += padNum(azimuth, 3);
        pkt += "\n";
        sendRS485(pkt);
    }
}

// ==================== ЧТЕНИЕ RS485 ====================
void readRS485() {
    while (rs485.available()) {
        char c = rs485.read();
        if (c == '\n') {
            parsePacket(rxBuffer);
            rxBuffer = "";
        } else {
            rxBuffer += c;
            if (rxBuffer.length() > 32) rxBuffer = "";
        }
    }
}

void parsePacket(String p) {
    p.trim();

    if (p.startsWith("H:") && p.indexOf("V:") > 0) {
        int vPos = p.indexOf("V:");
        angleH = constrain(p.substring(2, vPos).toInt(), 0, 180);
        angleV = constrain(p.substring(vPos + 2).toInt(), 0, 180);
        Serial.print(F("RX angles H="));
        Serial.print(angleH);
        Serial.print(F(" V="));
        Serial.println(angleV);
    }
    else if (p.startsWith("S:")) {
        stabilizationMode = (p.substring(2).toInt() == 1);
        if (stabilizationMode) {
            integral = 0;
            errPrev = 0;
            lastPid = millis();
        }
    }
    else if (p.startsWith("T:")) {
        targetAzimuth = p.substring(2).toInt();
        if (targetAzimuth < 0) targetAzimuth += 360;
    }
    else if (p.startsWith("C:")) {
        int mode = p.substring(2).toInt();
        if (mode == 0) {
            startCalibration();
        }
    }
}

// ==================== PID СТАБИЛИЗАЦИЯ ====================
void stabilizeWithPid(unsigned long now) {
    float dt = (now - lastPid) / 1000.0;
    if (dt < 0.01) dt = 0.01;
    lastPid = now;

    float err = targetAzimuth - azimuth;
    while (err > 180) err -= 360;
    while (err < -180) err += 360;

    if (abs(err) < 2.0) err = 0;

    float P = Kp * err;
    integral += err * dt;
    integral = constrain(integral, -100, 100);
    float I = Ki * integral;
    float D = Kd * (err - errPrev) / dt;
    errPrev = err;

    float out = P + I + D;
    out = constrain(out, -3.0, 3.0);

    if (abs(err) > 2.0) {
        angleH = constrain(angleH + (int)out, 0, 180);
    }
}

// ==================== ОТПРАВКА RS485 ====================
void sendRS485(String data) {
    digitalWrite(RS485_DE_RE, HIGH);
    delayMicroseconds(50);
    rs485.print(data);
    rs485.flush();
    delayMicroseconds(50);
    digitalWrite(RS485_DE_RE, LOW);
}

// ==================== КАЛИБРОВКА ====================
void startCalibration() {
    calibrating = true;
    calibStep = 0;
    calibStart = millis();
    Serial.println(F("=== FULL CALIBRATION STARTED ==="));
    Serial.println(F("Step 1: Keep antenna STILL (accel + gyro)"));
}

void runCalibration() {
    unsigned long elapsed = millis() - calibStart;

    if (calibStep == 0) {
        if (elapsed < 10000) {
            if (elapsed % 2000 < 100) {
                Serial.print(F("Accel+Gyro calib: "));
                Serial.print((10000 - elapsed) / 1000);
                Serial.println(F(" sec left"));
            }
            IMU.calibrateAccelGyro(&calib);
        } else if (elapsed < 30000) {
            if (elapsed < 12000) {
                Serial.println(F("Now ROTATE antenna 360 degrees"));
            }
            if (elapsed % 2000 < 100) {
                Serial.print(F("Mag calib: "));
                Serial.print((30000 - elapsed) / 1000);
                Serial.println(F(" sec left"));
            }
            IMU.calibrateMag(&calib);
        } else {
            finishCalibration();
        }
    }
}

void finishCalibration() {
    calibrating = false;
    saveCalibration();

    Serial.println(F("=== CALIBRATION DONE ==="));
    Serial.print(F("Accel bias: "));
    Serial.print(calib.accelBias[0]);
    Serial.print(F(", "));
    Serial.print(calib.accelBias[1]);
    Serial.print(F(", "));
    Serial.println(calib.accelBias[2]);

    Serial.print(F("Gyro bias: "));
    Serial.print(calib.gyroBias[0]);
    Serial.print(F(", "));
    Serial.print(calib.gyroBias[1]);
    Serial.print(F(", "));
    Serial.println(calib.gyroBias[2]);

    Serial.print(F("Mag bias: "));
    Serial.print(calib.magBias[0]);
    Serial.print(F(", "));
    Serial.print(calib.magBias[1]);
    Serial.print(F(", "));
    Serial.println(calib.magBias[2]);

    sendRS485("CALIB:OK\n");
}

void saveCalibration() {
    int addr = EEPROM_IMU_BASE;
    for (int i = 0; i < 3; i++) {
        writeInt(addr, calib.accelBias[i]); addr += 2;
    }
    for (int i = 0; i < 3; i++) {
        writeInt(addr, calib.gyroBias[i]); addr += 2;
    }
    for (int i = 0; i < 3; i++) {
        writeInt(addr, calib.magBias[i]); addr += 2;
    }
    EEPROM.write(EEPROM_IMU_FLAG, EEPROM_CALIB_VALUE);

    Serial.println(F("Calibration saved to EEPROM"));
}

void loadCalibration() {
    if (EEPROM.read(EEPROM_IMU_FLAG) == EEPROM_CALIB_VALUE) {
        int addr = EEPROM_IMU_BASE;
        for (int i = 0; i < 3; i++) {
            calib.accelBias[i] = readInt(addr); addr += 2;
        }
        for (int i = 0; i < 3; i++) {
            calib.gyroBias[i] = readInt(addr); addr += 2;
        }
        for (int i = 0; i < 3; i++) {
            calib.magBias[i] = readInt(addr); addr += 2;
        }
        calib.valid = true;
        Serial.println(F("IMU calibration loaded from EEPROM"));
    } else {
        Serial.println(F("No IMU calibration in EEPROM"));
    }
}

void writeInt(int addr, int value) {
    EEPROM.write(addr, highByte(value));
    EEPROM.write(addr + 1, lowByte(value));
}

int readInt(int addr) {
    return (EEPROM.read(addr) << 8) | EEPROM.read(addr + 1);
}

// ==================== УТИЛИТЫ ====================
String padNum(int v, byte w) {
    String s = String(v);
    while (s.length() < w) s = "0" + s;  // ✅ ИСПРАВЛЕНО: нули вместо пробелов
    return s;
}
